/**
 * @module generator
 * @description Minimal artifact generation for Claude Code configurations.
 *
 * This module handles only deterministic, non-AI-generated artifacts:
 * - settings.json — Permission patterns based on detected tech stack
 * - Directory creation — Ensures .claude/ subdirectories exist
 *
 * All content files (CLAUDE.md, skills, agents, rules, commands) are now
 * generated by Claude itself via the expanded prompt in prompt.ts.
 *
 * @example
 * import { writeSettings, ensureDirectories } from './generator.js';
 *
 * ensureDirectories('/path/to/project');
 * writeSettings('/path/to/project', techStack);
 */

import fs from "node:fs";
import path from "node:path";
import type { TechStack } from "./types.js";

// ============================================================================
// Directory Management
// ============================================================================

/**
 * Ensure all required .claude/ subdirectories exist.
 */
export function ensureDirectories(rootDir: string): void {
  const dirs = [".claude", ".claude/skills", ".claude/agents", ".claude/rules", ".claude/commands"];

  for (const dir of dirs) {
    fs.mkdirSync(path.join(rootDir, dir), { recursive: true });
  }
}

// ============================================================================
// Settings Generator
// ============================================================================

/**
 * Generate settings.json content with permission patterns based on detected tech stack.
 * This must remain deterministic in code — not AI-generated.
 */
export function generateSettings(stack: TechStack): { path: string; content: string } {
  const permissions: string[] = ["Read(**)", "Edit(**)", "Write(.claude/**)", "Bash(git:*)"];

  // Add package manager permissions
  const pkgManagers = ["npm", "yarn", "pnpm", "bun", "npx"];
  for (const pm of pkgManagers) {
    permissions.push(`Bash(${pm}:*)`);
  }

  // Add language-specific permissions
  if (stack.languages.includes("typescript") || stack.languages.includes("javascript")) {
    permissions.push("Bash(node:*)", "Bash(tsc:*)");
  }

  if (stack.languages.includes("python")) {
    permissions.push(
      "Bash(python:*)",
      "Bash(pip:*)",
      "Bash(poetry:*)",
      "Bash(pytest:*)",
      "Bash(uvicorn:*)"
    );
  }

  if (stack.languages.includes("go")) {
    permissions.push("Bash(go:*)");
  }

  if (stack.languages.includes("rust")) {
    permissions.push("Bash(cargo:*)", "Bash(rustc:*)");
  }

  if (stack.languages.includes("ruby")) {
    permissions.push("Bash(ruby:*)", "Bash(bundle:*)", "Bash(rails:*)", "Bash(rake:*)");
  }

  // Add testing framework permissions
  if (stack.testingFramework) {
    const testCommands: Record<string, string[]> = {
      jest: ["jest:*"],
      vitest: ["vitest:*"],
      playwright: ["playwright:*"],
      cypress: ["cypress:*"],
      pytest: ["pytest:*"],
      rspec: ["rspec:*"],
    };
    const cmds = testCommands[stack.testingFramework];
    if (cmds) {
      permissions.push(...cmds.map((c) => `Bash(${c})`));
    }
  }

  // Add linter/formatter permissions
  if (stack.linter) {
    permissions.push(`Bash(${stack.linter}:*)`);
  }
  if (stack.formatter) {
    permissions.push(`Bash(${stack.formatter}:*)`);
  }

  // Add common utility permissions
  permissions.push(
    "Bash(ls:*)",
    "Bash(mkdir:*)",
    "Bash(cat:*)",
    "Bash(echo:*)",
    "Bash(grep:*)",
    "Bash(find:*)"
  );

  // Add Docker if present
  if (stack.hasDocker) {
    permissions.push("Bash(docker:*)", "Bash(docker-compose:*)");
  }

  const settings = {
    $schema: "https://json.schemastore.org/claude-code-settings.json",
    permissions: {
      allow: [...new Set(permissions)], // Deduplicate
    },
  };

  return {
    path: ".claude/settings.json",
    content: JSON.stringify(settings, null, 2),
  };
}

// ============================================================================
// Settings Writer
// ============================================================================

/**
 * Write settings.json to the project's .claude/ directory.
 */
export function writeSettings(rootDir: string, stack: TechStack): void {
  const { path: settingsPath, content } = generateSettings(stack);
  const fullPath = path.join(rootDir, settingsPath);
  const dir = path.dirname(fullPath);

  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(fullPath, content);
}
